const iframe_runtime = require('iframe-runtime')

module.exports = virtual_device

// manages local iframe devices and their links
function virtual_device (opts = {}) {
  const document = opts.document || globalThis.document
  const state = { devices: new Map(), next_id: 1 }
  const api = { create, connect, disconnect, send, get, list, close, close_all }
  return api

  function create (code, opts = {}) {
    const id = opts.id || `device-${state.next_id++}`
    if (state.devices.has(id)) throw new Error(`Device already exists: ${id}`)
    const record = {
      id,
      closed: false,
      peers: new Set(),
      port: null,
      resolve_ready: null,
      reject_ready: null,
      receive: null,
      device: null
    }
    const ready = new Promise(store_ready)
    const runtime_opts = {
      document,
      mode: opts.mode || 'sandboxed',
      title: opts.title || `Virtual device ${id}`
    }
    const view = iframe_runtime(code, on_ready, runtime_opts)
    const device = { id, view, ready, port: null }
    record.device = device
    state.devices.set(id, record)
    return device

    function store_ready (resolve, reject) {
      record.resolve_ready = resolve
      record.reject_ready = reject
    }

    function on_ready (port) {
      if (record.closed) return port.close()
      record.port = device.port = port
      record.receive = receive
      port.addEventListener('message', receive)
      record.resolve_ready(device)
    }

    // send iframe messages through the host router
    function receive (event) {
      const message = event.data || {}
      if (message.type !== 'virtual-send') return
      try {
        route({ from: id, to: message.to, data: message.data })
      } catch (error) {
        port_error({ record, to: message.to, error })
      }
    }
  }

  function connect (first_id, second_id) {
    const first = require_device(first_id)
    const second = require_device(second_id)
    first.peers.add(second_id)
    second.peers.add(first_id)
  }

  function disconnect (first_id, second_id) {
    const first = require_device(first_id)
    const second = require_device(second_id)
    first.peers.delete(second_id)
    second.peers.delete(first_id)
  }

  function send ({ from, to, data }) { route({ from, to, data }) }

  // only linked devices can talk
  function route ({ from, to, data }) {
    const source = require_device(from)
    const target = require_device(to)
    if (!source.peers.has(to)) throw new Error(`Devices are not connected: ${from}, ${to}`)
    target.port.postMessage({ type: 'virtual-message', from, data })
  }

  function get (id) { return state.devices.get(id)?.device }

  function list () { return Array.from(state.devices.values(), get_public_device) }

  function get_public_device (record) { return record.device }

  // remove everything tied to this device
  function close (id) {
    const record = state.devices.get(id)
    if (!record) return false
    record.closed = true
    for (const peer of state.devices.values()) peer.peers.delete(id)
    state.devices.delete(id)
    if (record.port) record.port.removeEventListener('message', record.receive)
    else record.reject_ready(new Error(`Device closed before ready: ${id}`))
    record.device.view.close()
    return true
  }

  function close_all () {
    for (const id of Array.from(state.devices.keys())) close(id)
  }

  function require_device (id) {
    const record = state.devices.get(id)
    if (!record) throw new Error(`Unknown device: ${id}`)
    return record
  }

  function port_error ({ record, to, error }) {
    record.port.postMessage({ type: 'virtual-error', to, error: error.message })
  }
}
